for idx,lang in enumerate(['russian','english']):
 remaining=set(updates)
 for p in sorted((R/f'localisation/{lang}').glob('*.yml')):
  s=p.read_text(encoding='utf-8-sig');original=s
  for k in list(remaining):
   pattern=r'(?m)^\s*'+re.escape(k)+r':(?:\d+)?\s*".*"\s*$'
   s,n=re.subn(pattern,lambda m:' '+k+':0 "'+updates[k][idx]+'"',s)
   if n:remaining.remove(k)
  if s!=original:p.write_text(s,encoding='utf-8-sig')
 assert not remaining,remaining
 lines=['l_'+lang+':']+[' '+k+':0 "'+v[idx]+'"' for k,v in new.items()]
 (R/f'localisation/{lang}/JPT_three_heads_l_{lang}.yml').write_text('\n'.join(lines)+'\n',encoding='utf-8-sig')
print('RU/EN political localisation updated')
